import{c as r,a1 as i,U as o,j as l,g as t,o as n,a6 as c,p as u,n as d}from"./chunks/framework.h4W4t1IS.js";const w=JSON.parse('{"title":"Intégration Swing dans MVC","description":"","frontmatter":{"title":"Intégration Swing dans MVC","status":"ready","tags":["swing","all"],"authors":["Jean-François Dion"],"reviewers":[]},"headers":[],"relativePath":"swing/mvc-swing.md","filePath":"swing/mvc-swing.md"}'),p={name:"swing/mvc-swing.md"},m={id:"frontmatter-title",tabindex:"-1"};function h(a,e,g,f,v,b){const s=i("Icon");return o(),l("div",null,[t("h1",m,[n(c(a.$frontmatter.title)+" ",1),e[0]||(e[0]=t("a",{class:"header-anchor",href:"#frontmatter-title","aria-label":'Permalink to "{{ $frontmatter.title }}"'},"​",-1)),e[1]||(e[1]=n()),u(s,{icon:"mdi:bell-circle",style:{color:"var(--vp-c-tip-1)","vertical-align":"-0.1em","margin-left":"0.3em"},"aria-label":"Nouveau contenu"})]),e[2]||(e[2]=d(`<p>L&#39;intégration de Java Swing dans <a href="/420-w30-sf-po2/lexique.html#mvc" class="lexicon-link" title="Patron architectural en trois couches : le modèle (domaine, ignore tout du reste), la vue (affiche des DTOs, ignore le modèle), le contrôleur (orchestre les deux, connaît modèle ET vue).">MVC</a> demande de confiner les classes Swing à la <strong>couche vue</strong> et de faire respecter les contraintes de dépendances.</p><h2 id="objectifs-d-apprentissage" tabindex="-1">Objectifs d&#39;apprentissage <a class="header-anchor" href="#objectifs-d-apprentissage" aria-label="Permalink to &quot;Objectifs d&#39;apprentissage&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">Après cette section, tu seras capable de...</p><ul><li>Identifier où placer chaque classe Swing dans l&#39;architecture</li><li>Expliquer pourquoi le contrôleur ne doit dépendre d&#39;aucun type Swing</li><li>Décrire comment une vue Swing transmet une action de l&#39;utilisateur</li></ul></div><h2 id="ou-vit-swing" tabindex="-1">Où vit Swing? <a class="header-anchor" href="#ou-vit-swing" aria-label="Permalink to &quot;Où vit Swing?&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Couche</th><th>Classes</th><th>Connaît Swing?</th></tr></thead><tbody><tr><td><strong>Vue</strong></td><td><code>JFrame</code>, <code>JPanel</code>, <code>JButton</code>, <code>ActionListener</code></td><td>Oui</td></tr><tr><td><strong>Contrôleur</strong></td><td>Contrôleurs</td><td>Non</td></tr><tr><td><strong>Modèle</strong></td><td><a href="/420-w30-sf-po2/lexique.html#entite" class="lexicon-link" title="Objet qui représente un concept ou un élément du domaine d&#39;affaire, généralement identifiable par un identifiant unique et ayant une identité propre.">Entités</a>, repositories</td><td>Non</td></tr></tbody></table><p>Le contrôleur dépend d&#39;une <strong><a href="/420-w30-sf-po2/lexique.html#interface" class="lexicon-link" title="Contrat qui définit un ensemble de méthodes qu&#39;une classe doit implémenter, sans fournir d&#39;implémentation concrète. Permet de définir des comportements communs pour différentes classes.">interface</a></strong> de vue qui ne mentionne aucun type Swing. C&#39;est ce qui permet de le tester avec une doublure de la vue.</p><h2 id="transmettre-une-action-de-l-utilisateur" tabindex="-1">Transmettre une action de l&#39;utilisateur <a class="header-anchor" href="#transmettre-une-action-de-l-utilisateur" aria-label="Permalink to &quot;Transmettre une action de l&#39;utilisateur&quot;">​</a></h2><p>La vue implémente <code>ActionListener</code>. Lorsqu&#39;un bouton est cliqué, elle ne contacte <strong>aucun contrôleur</strong> directement : elle transforme l&#39;action en requête et la confie au <a href="/420-w30-sf-po2/lexique.html#routeur" class="lexicon-link" title="Composante qui achemine chaque requête émise par une vue vers le contrôleur approprié, de sorte que la vue n&#39;a pas à connaître le contrôleur.">Routeur</a>.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Clic sur un bouton</span></span>
<span class="line"><span>   → actionPerformed(e) dans la vue</span></span>
<span class="line"><span>   → requête confiée au Routeur</span></span>
<span class="line"><span>   → contrôleur approprié</span></span></code></pre></div><h2 id="contraintes-respectees" tabindex="-1">Contraintes respectées <a class="header-anchor" href="#contraintes-respectees" aria-label="Permalink to &quot;Contraintes respectées&quot;">​</a></h2><ul><li>La vue ne connaît pas le modèle : elle reçoit des <a href="/420-w30-sf-po2/lexique.html#dto" class="lexicon-link" title="Objet immuable dont le seul rôle est de transporter des données entre les couches (souvent modèle ↔ vue), sans comportement. Créé et transformé par un convertisseur.">DTO</a></li><li>La vue ne connaît pas le contrôleur : elle passe par le Routeur</li><li>Le contrôleur ne connaît pas Swing : il dépend d&#39;une interface de vue</li><li>Le modèle n&#39;a aucune dépendance sur <code>javax.swing</code></li></ul>`,11))])}const x=r(p,[["render",h]]);export{w as __pageData,x as default};
